import os
import random

r = random.Random(int(os.environ["SEED"]) * 1000 + int(os.environ["INDEX"]))
i = int(os.environ["INDEX"])
f = r.choice([20, 25, 30, 35])
while True:
    if i % 4 == 0:
        u = [f + r.randint(-3, 6) for _ in range(3)]
    elif i % 4 == 1:
        u = [f + r.randint(2, 8), f + r.randint(2, 8), f - r.choice([3, 4])]
    elif i % 4 == 2:
        u = [f + r.randint(-3, 1) for _ in range(3)]
    else:
        u = [f + r.randint(4, 9), f + r.randint(4, 9), f - r.randint(4, 6)]
    if sum(u) != 3 * f:
        break
r.shuffle(u)
print(f)
for x in u:
    print(x)

