jam_kerja = int(input())
upah_per_jam = int(input())
if jam_kerja <= 40:
    upah = jam_kerja * upah_per_jam
elif jam_kerja <= 48:
    upah = 40 * upah_per_jam + (jam_kerja - 40) * upah_per_jam * 3 // 2
else:
    upah = 40 * upah_per_jam + 8 * upah_per_jam * 3 // 2 + (jam_kerja - 48) * upah_per_jam * 2
print(f"Upah: Rp {upah}")

